import React from 'react';

import {
  StyledMultiDimensionIcon,
  StyledInnerHighlightedIcon,
  StyledOuterHighlightedIcon,
} from './styles/DataPointShape.styles.js';

/** @internal */
export interface MultiDataPointShapeProps {
  active?: boolean;
  color: string;
}

/** @internal */
export const MultiDataPointShape = ({
  color,
  active = false,
}: MultiDataPointShapeProps) => {
  return active ? (
    <StyledOuterHighlightedIcon color={color}>
      <StyledInnerHighlightedIcon color={color} />
    </StyledOuterHighlightedIcon>
  ) : (
    <StyledMultiDimensionIcon color={color} />
  );
};

MultiDataPointShape['displayName'] = 'MultiDataPointShape';
